    try:
        return gateway.charge(customer_id, amount_cents)
    except Exception:
        logger.exception("charge failed for customer %s", customer_id)
        raise

import os

from flask import Flask, request, send_file

app = Flask(__name__)
PUBLIC_DIR = "/srv/public"


# Serve a public file by name.
@app.route("/download")
def download():
    name = request.args.get("name", "")
    return send_file(os.path.join(PUBLIC_DIR, name))

